INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','contrast-concession','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"contrast-concession","title":"Contrast and concession: although, despite and whereas","level":"B2","order":46,"summary":"Show that two ideas contrast, or that something happens in spite of an obstacle.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Although and even though","Despite and in spite of","Whereas and while","However and nevertheless"],"rules":[{"title":"Although and even though","explanation":"Although, though and even though introduce a subordinate clause. They present information that contrasts with the main clause or might have led to a different expectation. Even though often makes the contrast stronger.","pattern":"**Although it rained**, we went out.","commonMistakes":["Do not normally combine although and but to mark the same relation in one standard sentence."],"examples":["“**Although** we had prepared the visitor guide, the supervisor asked for another check.”","“**Although** we had restored the old portrait, the supervisor asked for another check.”"],"skill":"form"},{"title":"Despite and in spite of","explanation":"Despite and in spite of take a noun phrase or -ing expression. To follow them with a finite clause, use the fact that. Despite does not itself take of.","pattern":"**Despite the rain**, we went out. / **Despite the fact that it rained**, we went out.","commonMistakes":["Despite of is not the standard phrase; use despite or in spite of."],"examples":["“Despite **preparing** the visitor guide, we still had plenty to do.”","“Despite **restoring** the old portrait, we still had plenty to do.”"],"skill":"meaning"},{"title":"Whereas and while","explanation":"Whereas and contrastive while compare two facts, preferences or situations. While also has a time meaning, so ensure that context makes the contrast clear. Whereas is particularly useful when balancing one fact against another.","pattern":"She likes tea, **whereas** he prefers coffee.","commonMistakes":["Whereas normally introduces a clause, not a noun phrase by itself."],"examples":["Choose the correct concession phrase: “**In spite of** the difficulty, we managed to prepare the visitor guide.”","Choose the correct concession phrase: “**In spite of** the difficulty, we managed to restore the old portrait.”"],"skill":"contrast"},{"title":"However and nevertheless","explanation":"However and nevertheless are linking adverbs, not ordinary coordinating conjunctions. They can start a new sentence or follow a semicolon between independent clauses. Their punctuation differs from but even when the contrast is similar.","pattern":"It rained**; however,** we went out.","commonMistakes":["It rained, however we went out is a comma splice in ordinary formal prose."],"examples":["Choose formal punctuation linking two complete clauses: “We prepared the visitor guide **;** however, the supervisor requested a change.”","Choose formal punctuation linking two complete clauses: “We restored the old portrait **;** however, the supervisor requested a change.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"00a1e58b-c48e-518d-a967-5554c7ae61e4","topicSlug":"contrast-concession","level":"B2","prompt":"“____ we had prepared the visitor guide, the supervisor asked for another check.”","choices":[{"id":"A","text":"However"},{"id":"B","text":"Although"},{"id":"C","text":"Despite"},{"id":"D","text":"In spite"}],"answerId":"B","hint":"The contrast is expressed by a **full finite clause**.","explanation":"**Although** introduces a finite concession clause with subject we and verb had ... .","keywords":["although-clause"],"skill":"although-clause","contextKey":"contrast-concession-1","fingerprint":"af14ff88d2e70bd729f86f0e180c6d840c45114a715881bcdaff940db41e809d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The contrast is expressed by a **full finite clause**.","**Although** introduces a finite concession clause with subject we and verb had ... .","Choose **Although**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"However is a linking adverb and does not subordinate this clause in the same way.","B":"**Although** introduces a finite concession clause with subject we and verb had ... .","C":"Despite normally takes a noun phrase or -ing expression, not this finite clause directly.","D":"The complete phrase is in spite of, and it still needs a suitable complement."}}},{"id":"f7db6b98-94cc-5823-a439-752ce6ac5ca5","topicSlug":"contrast-concession","level":"B2","prompt":"“Despite ____ the visitor guide, we still had plenty to do.”","choices":[{"id":"A","text":"prepared"},{"id":"B","text":"preparing"},{"id":"C","text":"prepare"},{"id":"D","text":"to prepare"}],"answerId":"B","hint":"Despite is followed by a **noun phrase or -ing clause**.","explanation":"After **despite**, use **preparing** to express the conceded activity.","keywords":["despite-gerund"],"skill":"despite-gerund","contextKey":"contrast-concession-1","fingerprint":"aa0420dd7c639db3ba3856035e5f21e75b478ddf3e3a64bc81dce762919af442","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Despite is followed by a **noun phrase or -ing clause**.","After **despite**, use **preparing** to express the conceded activity.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A past form alone does not form the required complement.","B":"After **despite**, use **preparing** to express the conceded activity.","C":"A bare base verb does not follow despite in this pattern.","D":"Despite does not take a to-infinitive here."}}},{"id":"6e059fc0-2c6c-57b0-a316-c8e2b0932486","topicSlug":"contrast-concession","level":"B2","prompt":"Choose the correct concession phrase: “____ the difficulty, we managed to prepare the visitor guide.”","choices":[{"id":"A","text":"Despite of"},{"id":"B","text":"In spite"},{"id":"C","text":"Although of"},{"id":"D","text":"In spite of"}],"answerId":"D","hint":"Distinguish the fixed forms **despite** and **in spite of**.","explanation":"**In spite of** is the complete three-word phrase before the noun phrase.","keywords":["despite-of-error"],"skill":"despite-of-error","contextKey":"contrast-concession-1","fingerprint":"a08434c0fa0f47ae8ffed8019b28718dd27fb42b6e1c71ec6181cec1face61e9","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Distinguish the fixed forms **despite** and **in spite of**.","**In spite of** is the complete three-word phrase before the noun phrase.","Choose **In spite of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Despite does not take of.","B":"In spite requires of before this noun phrase.","C":"Although introduces a clause and does not form although of.","D":"**In spite of** is the complete three-word phrase before the noun phrase."}}},{"id":"e7c67993-697c-5991-ad05-0412283eae6c","topicSlug":"contrast-concession","level":"B2","prompt":"Choose formal punctuation linking two complete clauses: “We prepared the visitor guide ____ however, the supervisor requested a change.”","choices":[{"id":"A","text":"of"},{"id":"B","text":";"},{"id":"C","text":","},{"id":"D","text":"no punctuation"}],"answerId":"B","hint":"However is a **linking adverb**; it does not make a comma alone sufficient.","explanation":"A **semicolon** separates the independent clauses before linking adverb however.","keywords":["however-punctuation"],"skill":"however-punctuation","contextKey":"contrast-concession-1","fingerprint":"139be33f3aa5ae271da0e8bf308f72a87c7e27b4847aae1321622ce09aa3c1a9","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["However is a **linking adverb**; it does not make a comma alone sufficient.","A **semicolon** separates the independent clauses before linking adverb however.","Choose **;**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Of cannot connect these independent clauses.","B":"A **semicolon** separates the independent clauses before linking adverb however.","C":"A comma alone would create a comma splice.","D":"The clauses would run together."}}},{"id":"3b08a95b-48e1-58a5-a54b-1a1009eb7edd","topicSlug":"contrast-concession","level":"B2","prompt":"“____ we had restored the old portrait, the supervisor asked for another check.”","choices":[{"id":"A","text":"However"},{"id":"B","text":"Although"},{"id":"C","text":"Despite"},{"id":"D","text":"In spite"}],"answerId":"B","hint":"The contrast is expressed by a **full finite clause**.","explanation":"**Although** introduces a finite concession clause with subject we and verb had ... .","keywords":["although-clause"],"skill":"although-clause","contextKey":"contrast-concession-2","fingerprint":"d08c70087f599c6bb33e4fa15124845322bc0133076f4636f05e96b2ae4e6272","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The contrast is expressed by a **full finite clause**.","**Although** introduces a finite concession clause with subject we and verb had ... .","Choose **Although**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"However is a linking adverb and does not subordinate this clause in the same way.","B":"**Although** introduces a finite concession clause with subject we and verb had ... .","C":"Despite normally takes a noun phrase or -ing expression, not this finite clause directly.","D":"The complete phrase is in spite of, and it still needs a suitable complement."}}},{"id":"30dfff24-954b-5111-ae23-503ae3400250","topicSlug":"contrast-concession","level":"B2","prompt":"“Despite ____ the old portrait, we still had plenty to do.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"restore"},{"id":"C","text":"to restore"},{"id":"D","text":"restored"}],"answerId":"A","hint":"Despite is followed by a **noun phrase or -ing clause**.","explanation":"After **despite**, use **restoring** to express the conceded activity.","keywords":["despite-gerund"],"skill":"despite-gerund","contextKey":"contrast-concession-2","fingerprint":"958edcc6e98346afdb72aab124b112fb152c510de55ab4635b1be746b4b71388","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Despite is followed by a **noun phrase or -ing clause**.","After **despite**, use **restoring** to express the conceded activity.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After **despite**, use **restoring** to express the conceded activity.","B":"A bare base verb does not follow despite in this pattern.","C":"Despite does not take a to-infinitive here.","D":"A past form alone does not form the required complement."}}},{"id":"ed9b446f-17d7-5c4e-a447-81b1a526ed82","topicSlug":"contrast-concession","level":"B2","prompt":"Choose the correct concession phrase: “____ the difficulty, we managed to restore the old portrait.”","choices":[{"id":"A","text":"In spite"},{"id":"B","text":"Although of"},{"id":"C","text":"In spite of"},{"id":"D","text":"Despite of"}],"answerId":"C","hint":"Distinguish the fixed forms **despite** and **in spite of**.","explanation":"**In spite of** is the complete three-word phrase before the noun phrase.","keywords":["despite-of-error"],"skill":"despite-of-error","contextKey":"contrast-concession-2","fingerprint":"6d79acde1a1d94f52c361ba46e31bae80096b50f8dae13f3b5fe0e9d80db2851","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Distinguish the fixed forms **despite** and **in spite of**.","**In spite of** is the complete three-word phrase before the noun phrase.","Choose **In spite of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"In spite requires of before this noun phrase.","B":"Although introduces a clause and does not form although of.","C":"**In spite of** is the complete three-word phrase before the noun phrase.","D":"Despite does not take of."}}},{"id":"3a6c6be5-810b-5ea0-a612-37dfb8377ff0","topicSlug":"contrast-concession","level":"B2","prompt":"Choose formal punctuation linking two complete clauses: “We restored the old portrait ____ however, the supervisor requested a change.”","choices":[{"id":"A","text":","},{"id":"B","text":"no punctuation"},{"id":"C","text":"of"},{"id":"D","text":";"}],"answerId":"D","hint":"However is a **linking adverb**; it does not make a comma alone sufficient.","explanation":"A **semicolon** separates the independent clauses before linking adverb however.","keywords":["however-punctuation"],"skill":"however-punctuation","contextKey":"contrast-concession-2","fingerprint":"f2871c34fee80290af04788bf227c6c2af7bc93fcd83eef83809c9544876b6d0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["However is a **linking adverb**; it does not make a comma alone sufficient.","A **semicolon** separates the independent clauses before linking adverb however.","Choose **;**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A comma alone would create a comma splice.","B":"The clauses would run together.","C":"Of cannot connect these independent clauses.","D":"A **semicolon** separates the independent clauses before linking adverb however."}}},{"id":"b7dcc97e-2299-5ef3-a57e-4cc693c621a0","topicSlug":"contrast-concession","level":"B2","prompt":"“____ we had measured the garden fence, the supervisor asked for another check.”","choices":[{"id":"A","text":"Although"},{"id":"B","text":"Despite"},{"id":"C","text":"In spite"},{"id":"D","text":"However"}],"answerId":"A","hint":"The contrast is expressed by a **full finite clause**.","explanation":"**Although** introduces a finite concession clause with subject we and verb had ... .","keywords":["although-clause"],"skill":"although-clause","contextKey":"contrast-concession-3","fingerprint":"8b977d2905c67e19930d96750ffd77b6281b628f473287aa0c0ea6612ff68dec","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The contrast is expressed by a **full finite clause**.","**Although** introduces a finite concession clause with subject we and verb had ... .","Choose **Although**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Although** introduces a finite concession clause with subject we and verb had ... .","B":"Despite normally takes a noun phrase or -ing expression, not this finite clause directly.","C":"The complete phrase is in spite of, and it still needs a suitable complement.","D":"However is a linking adverb and does not subordinate this clause in the same way."}}},{"id":"ccd2d91f-c2bb-5030-a846-7846549b4194","topicSlug":"contrast-concession","level":"B2","prompt":"“Despite ____ the garden fence, we still had plenty to do.”","choices":[{"id":"A","text":"to measure"},{"id":"B","text":"measured"},{"id":"C","text":"measuring"},{"id":"D","text":"measure"}],"answerId":"C","hint":"Despite is followed by a **noun phrase or -ing clause**.","explanation":"After **despite**, use **measuring** to express the conceded activity.","keywords":["despite-gerund"],"skill":"despite-gerund","contextKey":"contrast-concession-3","fingerprint":"3f45cd020228887947f5d82cb3fdbe0f01beec8c3ae2b62ae6c984e2e22b9439","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Despite is followed by a **noun phrase or -ing clause**.","After **despite**, use **measuring** to express the conceded activity.","Choose **measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Despite does not take a to-infinitive here.","B":"A past form alone does not form the required complement.","C":"After **despite**, use **measuring** to express the conceded activity.","D":"A bare base verb does not follow despite in this pattern."}}},{"id":"3253326d-11a6-5274-ad48-432a302c67af","topicSlug":"contrast-concession","level":"B2","prompt":"Choose the correct concession phrase: “____ the difficulty, we managed to measure the garden fence.”","choices":[{"id":"A","text":"Although of"},{"id":"B","text":"In spite of"},{"id":"C","text":"Despite of"},{"id":"D","text":"In spite"}],"answerId":"B","hint":"Distinguish the fixed forms **despite** and **in spite of**.","explanation":"**In spite of** is the complete three-word phrase before the noun phrase.","keywords":["despite-of-error"],"skill":"despite-of-error","contextKey":"contrast-concession-3","fingerprint":"b1d0a61c33abef178e85a3a8d5503551142f0394785e708d88b4b3e33ae974f0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Distinguish the fixed forms **despite** and **in spite of**.","**In spite of** is the complete three-word phrase before the noun phrase.","Choose **In spite of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Although introduces a clause and does not form although of.","B":"**In spite of** is the complete three-word phrase before the noun phrase.","C":"Despite does not take of.","D":"In spite requires of before this noun phrase."}}},{"id":"b24515e4-64ac-50d9-ac43-9463459190cf","topicSlug":"contrast-concession","level":"B2","prompt":"Choose formal punctuation linking two complete clauses: “We measured the garden fence ____ however, the supervisor requested a change.”","choices":[{"id":"A","text":";"},{"id":"B","text":","},{"id":"C","text":"no punctuation"},{"id":"D","text":"of"}],"answerId":"A","hint":"However is a **linking adverb**; it does not make a comma alone sufficient.","explanation":"A **semicolon** separates the independent clauses before linking adverb however.","keywords":["however-punctuation"],"skill":"however-punctuation","contextKey":"contrast-concession-3","fingerprint":"c1e97c31045906d40714420f3409e6ce1251d8e2e620f98f3bcd7fc41ad9cd08","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["However is a **linking adverb**; it does not make a comma alone sufficient.","A **semicolon** separates the independent clauses before linking adverb however.","Choose **;**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A **semicolon** separates the independent clauses before linking adverb however.","B":"A comma alone would create a comma splice.","C":"The clauses would run together.","D":"Of cannot connect these independent clauses."}}},{"id":"157eb6fb-903a-58e1-a955-6c25829d2ac6","topicSlug":"contrast-concession","level":"B2","prompt":"“____ we had translated the travel leaflet, the supervisor asked for another check.”","choices":[{"id":"A","text":"In spite"},{"id":"B","text":"However"},{"id":"C","text":"Although"},{"id":"D","text":"Despite"}],"answerId":"C","hint":"The contrast is expressed by a **full finite clause**.","explanation":"**Although** introduces a finite concession clause with subject we and verb had ... .","keywords":["although-clause"],"skill":"although-clause","contextKey":"contrast-concession-4","fingerprint":"89b5b19b1b7ec4416eef22cb5ffeae7d954f86b0d0f0a8683796d6fc2c27a6bd","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The contrast is expressed by a **full finite clause**.","**Although** introduces a finite concession clause with subject we and verb had ... .","Choose **Although**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The complete phrase is in spite of, and it still needs a suitable complement.","B":"However is a linking adverb and does not subordinate this clause in the same way.","C":"**Although** introduces a finite concession clause with subject we and verb had ... .","D":"Despite normally takes a noun phrase or -ing expression, not this finite clause directly."}}},{"id":"58c9c6d5-7f76-5d17-a4ce-cdd2f851d3fe","topicSlug":"contrast-concession","level":"B2","prompt":"“Despite ____ the travel leaflet, we still had plenty to do.”","choices":[{"id":"A","text":"to translate"},{"id":"B","text":"translated"},{"id":"C","text":"translating"},{"id":"D","text":"translate"}],"answerId":"C","hint":"Despite is followed by a **noun phrase or -ing clause**.","explanation":"After **despite**, use **translating** to express the conceded activity.","keywords":["despite-gerund"],"skill":"despite-gerund","contextKey":"contrast-concession-4","fingerprint":"6301eff9c243f0929384ac87560fe27cd8b80ebb242b38c0fda2676d8732ed7a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-contrast"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Despite is followed by a **noun phrase or -ing clause**.","After **despite**, use **translating** to express the conceded activity.","Choose **translating**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Despite does not take a to-infinitive here.","B":"A past form alone does not form the required complement.","C":"After **despite**, use **translating** to express the conceded activity.","D":"A bare base verb does not follow despite in this pattern."}}},{"id":"0870767f-523d-52ef-a3a4-4d5b46a19a90","topicSlug":"contrast-concession","level":"B2","prompt":"Choose the correct concession phrase: “____ the difficulty, we managed to translate the travel leaflet.”","choices":[{"id":"A","text":"In spite of"},{"id":"B","text":"Despite of"},{"id":"C","text":"In spite"},{"id":"D","text":"Although of"}],"answerId":"A","hint":"Distinguish the fixed forms **despite** and **in spite of**.","explanation":"**In spite of** is the complet