INSERT INTO grammar.grammar_quiz_items(id,topic_slug,level,prompt,choices,answer_id,hint,explanation,keywords,source,fingerprint,source_metadata)
SELECT (q->>'id')::uuid,q->>'topicSlug',q->>'level',q->>'prompt',q->'choices',q->>'answerId',q->>'hint',q->>'explanation',ARRAY(SELECT jsonb_array_elements_text(q->'keywords')),'seed',q->>'fingerprint',(q->'provenance')||jsonb_build_object('contentHash','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','skill',q->>'skill','contextKey',q->>'contextKey','teaching',q->'teaching')
FROM grammar.content_catalog_topics t CROSS JOIN LATERAL jsonb_array_elements(t.payload->'quizItems') q WHERE t.version='core-2026-09-v3' AND t.slug='contrast-concession'
ON CONFLICT(id) DO NOTHING;
DO $verify$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='contrast-concession' AND payload_md5='ec9eeb57e77eb2089298062117c7b867') THEN RAISE EXCEPTION 'Full payload mismatch'; END IF;
 IF (SELECT count(*) FROM grammar.grammar_quiz_items WHERE topic_slug='contrast-concession')<>200 THEN RAISE EXCEPTION 'Question count mismatch'; END IF;
END $verify$;
COMMIT;
